import{_ as a,o as t,c as e,a2 as i}from"./chunks/framework.BvlN9b-o.js";const k=JSON.parse('{"title":"快速开始：后端开发环境","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/getting-started/quickstart","contentType":"guide","prev":{"text":"创建自己的项目","link":"/getting-started/create-project"},"next":{"text":"项目结构","link":"/architecture/project-structure"}},"headers":[],"relativePath":"getting-started/quickstart.md","filePath":"getting-started/quickstart.md"}'),n={name:"getting-started/quickstart.md"};function h(p,s,r,d,l,o){return t(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="快速开始-后端开发环境" tabindex="-1">快速开始：后端开发环境 <a class="header-anchor" href="#快速开始-后端开发环境" aria-label="Permalink to &quot;快速开始：后端开发环境&quot;">​</a></h1><p>启动模板的 API 与依赖，确认 HTTP、PostgreSQL 和迁移正常，再进入自己的业务开发。</p><h2 id="_1-准备工具与副本" tabindex="-1">1. 准备工具与副本 <a class="header-anchor" href="#_1-准备工具与副本" aria-label="Permalink to &quot;1. 准备工具与副本&quot;">​</a></h2><p>使用仓库固定版本：Rust 1.96.0、Node 24.18.0、pnpm 11.17.0、just 1.58.0，以及能够运行 Linux 容器的 Docker / Compose。版本来源是 <code>rust-toolchain.toml</code>、<code>.node-version</code>、<code>package.json</code> 与 <code>.tool-versions</code>。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/CaiZongyuan/axum-saas-template.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> axum-saas-template</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>从仓库根目录执行。首次运行需要下载依赖和编译 Rust；开发脚本启动 PostgreSQL、Redis、RustFS、Mailpit，显式执行迁移并初始化存储，然后启动 API、Worker 与 Web。</p><p>没有 <code>.env</code> 时使用 <code>.env.example</code> 的开发默认值。需要覆盖端口或服务设置时建立本地 <code>.env</code>；所有配置来源见<a href="./../reference/config">配置参考</a>。</p><h2 id="_2-发出第一条真实请求" tabindex="-1">2. 发出第一条真实请求 <a class="header-anchor" href="#_2-发出第一条真实请求" aria-label="Permalink to &quot;2. 发出第一条真实请求&quot;">​</a></h2><p>保持开发入口运行，在另一个终端执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:18000/health/live</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:18000/health/ready</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:18000/api/v1/system/status</span></span></code></pre></div><p>预期均返回 HTTP 200，每个响应带有 <code>x-request-id</code>。status 返回 <code>status: &quot;ok&quot;</code>、<code>database: &quot;connected&quot;</code> 和实际 <code>schema_version</code>；版本随源码迁移改变。</p><p>live 证明进程运行；ready 核对依赖与完整迁移集合。API 启动不会自动修改数据库结构。</p><h2 id="_3-观察依赖失败与恢复" tabindex="-1">3. 观察依赖失败与恢复 <a class="header-anchor" href="#_3-观察依赖失败与恢复" aria-label="Permalink to &quot;3. 观察依赖失败与恢复&quot;">​</a></h2><p>只在自己的开发环境操作。另一个终端停止 PostgreSQL：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db-down</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:18000/health/ready</span></span></code></pre></div><p>ready 返回 503，live 仍返回 200。恢复数据库后重新请求：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> services-up</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:18000/health/ready</span></span></code></pre></div><p>ready 应恢复 200。若连接成功但迁移历史不匹配，运行 <code>just migrate</code> 并确认源码与数据库版本一致。</p><h2 id="_4-准备认证请求" tabindex="-1">4. 准备认证请求 <a class="header-anchor" href="#_4-准备认证请求" aria-label="Permalink to &quot;4. 准备认证请求&quot;">​</a></h2><p>默认 Web 为 <code>http://127.0.0.1:15400</code>，可以在 <code>/register</code> 创建开发账号。首个成功注册者为 Owner，后续为 Member；密码长度 12–128 字符。</p><p>自己的受保护 HTTP 接口复用当前 Session、可信 Origin 和 CSRF。接入方式见<a href="./../tutorials/sessions">认证与会话</a>，邮件恢复可通过 <a href="http://127.0.0.1:18025" target="_blank" rel="noreferrer">Mailpit</a>查看。</p><p>已有知识库示例展示<a href="./../tutorials/personal-documents">业务写入</a>、<a href="./../tutorials/library-grants">资源授权</a>和<a href="./../tutorials/document-exports">后台导出</a>，供自己实现业务时查阅。</p><h2 id="_5-进入开发循环" tabindex="-1">5. 进入开发循环 <a class="header-anchor" href="#_5-进入开发循环" aria-label="Permalink to &quot;5. 进入开发循环&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> generate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contracts:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span></code></pre></div><p>Rust DTO 定义合同，SDK 与类型从 OpenAPI 生成。自己的模块、迁移、路由和测试应同步增加。先阅读<a href="./../architecture/project-structure">项目结构</a>，再完成<a href="./../guides/new-module">新增业务模块</a>。</p><p>Rust <code>.rs</code> / <code>.toml</code> 变更会重启 API 与 Worker。新增 SQL 迁移后显式执行 <code>just migrate</code>，并重启开发入口使编译进二进制的迁移集合刷新。Web 使用 HMR。</p><h2 id="停止与排错" tabindex="-1">停止与排错 <a class="header-anchor" href="#停止与排错" aria-label="Permalink to &quot;停止与排错&quot;">​</a></h2><p><code>Ctrl+C</code> 停止宿主机 API/Worker/Web；<code>just services-down</code> 停止依赖并保留数据卷。</p><table tabindex="0"><thead><tr><th>症状</th><th>检查与恢复</th></tr></thead><tbody><tr><td>Docker 服务未就绪</td><td>确认 Docker daemon、镜像与端口，再启动开发入口</td></tr><tr><td>ready 返回 503</td><td>检查 PostgreSQL、显式迁移和当前源码 checksum</td></tr><tr><td>API 或 Web 端口占用</td><td>在 .env 修改 APP_PORT 或 WEB_PORT；相关地址由开发脚本派生</td></tr><tr><td>数据库端口改变</td><td>在 .env 修改 POSTGRES_PORT；DATABASE_URL 自动派生</td></tr><tr><td>healthy 但没有端口绑定</td><td>启动自检会终止；按提示停止占用者，再 force-recreate，不删除数据卷</td></tr><tr><td>请求失败</td><td>按 request_id 查 API JSON 日志，并核对公开错误</td></tr></tbody></table><p>本地文档通过 <code>just docs</code> 启动，默认地址为 <code>http://127.0.0.1:5174/axum-saas-template/docs/</code>。页脚的源码版本表示构建来源；需要复现某个版本时检出该提交再执行步骤。</p><hr><p>源码版本：<code>261be5bb90df</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/261be5bb90df09137bbc5c8523cb48285852a9a5/docs/getting-started/quickstart.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,32)])])}const u=a(n,[["render",h]]);export{k as __pageData,u as default};
